{
  "drugs": [
    {
      "generic": "oxycodone",
      "plain_purpose": "a strong pain medicine used when other pain treatments do not work",
      "common_side_effects": ["nausea", "constipation", "drowsiness", "dizziness"],
      "key_warning": "can cause addiction, abuse, overdose, and death"
    },
    {
      "generic": "acetaminophen",
      "plain_purpose": "a medicine that reduces fever and relieves minor aches and pains",
      "common_side_effects": ["rare skin reactions", "liver damage if taken too much"],
      "key_warning": "taking more than 4,000 mg in 24 hours can cause severe liver damage"
    },
    {
      "generic": "enoxaparin",
      "plain_purpose": "a blood thinner used to prevent and treat blood clots",
      "common_side_effects": ["bleeding", "anemia", "low platelet count", "injection site pain"],
      "key_warning": "can cause spinal or epidural blood clots that may lead to paralysis"
    },
    {
      "generic": "docusate",
      "plain_purpose": "a stool softener that helps relieve occasional constipation",
      "common_side_effects": ["stomach cramps", "diarrhea", "nausea"],
      "key_warning": "stop use and see a doctor if you have rectal bleeding or no bowel movement after use"
    },
    {
      "generic": "ondansetron",
      "plain_purpose": "a medicine that prevents nausea and vomiting from chemotherapy, radiation, or surgery",
      "common_side_effects": ["headache", "tiredness", "constipation", "diarrhea"],
      "key_warning": "can cause a dangerous heart rhythm problem called QT prolongation"
    }
  ]
}
